int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
        int error = 0;
        long timeout = *timeo_p;
        int result;

        sctp_association_getref(asoc);

        while (1) {
                if (asoc->state == SCTP_STATE_CLOSED) {
                        error = -EPIPE;
                        break;
                }

                if (msg_len <= asoc->sndbuf_available)
                        break;

                if (timeout <= 0) {
                        error = -EAGAIN;
                        break;
                }

                /* Wait for send buffer to have space */
                result = wait_event_interruptible_timeout(asoc->wait, 
                                                          (msg_len <= asoc->sndbuf_available),
                                                          timeout);
                if (result <= 0) {
                        if (result == 0)
                                error = -EAGAIN;
                        else
                                error = -EINTR;
                        break;
                }

                timeout = result;
        }

        sctp_association_putref(asoc);
        *timeo_p = timeout;
        return error;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
        int error = 0;
        long timeout = *timeo_p;
        long left;

        sctp_association_hold(asoc);

        while (1) {
                if (signal_pending(current)) {
                        error = -ERESTARTSYS;
                        break;
                }

                if (asoc->state == SCTP_STATE_CLOSED ||
                    asoc->state == SCTP_STATE_SHUTDOWN_PENDING ||
                    asoc->state == SCTP_STATE_SHUTDOWN) {
                        error = -EPIPE;
                        break;
                }

                if (msg_len <= sctp_freea(asoc)) {
                        break;
                }

                if (timeout <= 0) {
                        error = -EAGAIN;
                        break;
                }

                left = schedule_timeout(timeout);
                timeout = left;
        }

        *timeo_p = timeout;
        sctp_association_put(asoc);
        return error ? error : 0;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
        int error = 0;
        long timeout = *timeo_p;
        int retry = 1;
        int interruptible = 0;

        sctp_association_hold(asoc);

        while (retry) {
                if (unlikely(!atomic_read(&asoc->base.refcnt)))
                        break;

                if (asoc->state == SCTP_STATE_CLOSED ||
                    asoc->state == SCTP_STATE_SHUTDOWN) {
                        error = -EPIPE;
                        break;
                }

                if (msg_len <= asoc->sndbuf_used) {
                        retry = 0;
                        break;
                }

                if (timeout <= 0) {
                        error = -EAGAIN;
                        break;
                }

                if (interruptible)
                        schedule_timeout_uninterruptible(timeout);
                else
                        schedule_timeout(timeout);
                timeout = *timeo_p;
        }

        sctp_association_put(asoc);
        *timeo_p = timeout;
        return error;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
        int error = 0;
        int do_zap = 0;

        sctp_association_hold(asoc);

        while (1) {
                /* Check for errors, association state, and signals. */
                if (asoc->state == SCTP_STATE_CLOSED) {
                        error = -EPIPE;
                        break;
                }

                if (signal_pending(current)) {
                        error = -EAGAIN;
                        break;
                }

                if (msg_len <= asoc->ulpq.ulpq_free) {
                        error = 0;
                        break;
                }

                if (!*timeo_p) {
                        error = -EAGAIN;
                        break;
                }

                /* Wait for buffer space. */
                schedule();
                *timeo_p = *timeo_p - 1;
        }

        if (do_zap)
                sctp_association_put(asoc);

        return error;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
        int error = 0;
        long timeout = *timeo_p;
        int do_time_wait = 0;

        sctp_association_hold(asoc);

        while (1) {
                if (signal_pending(current)) {
                        error = -EINTR;
                        break;
                }

                if (msg_len <= asoc->sndbuf_left)
                        break;

                if (asoc->state == SCTP_STATE_SHUTDOWN || asoc->state == SCTP_STATE_SHUTDOWN_PENDING) {
                        error = -EPIPE;
                        break;
                }

                if (timeout <= 0) {
                        do_time_wait = 1;
                        break;
                }

                if (timeout > 0)
                        timeout = schedule_timeout_interruptible(timeout);
        }

        sctp_association_put(asoc);

        if (do_time_wait)
                *timeo_p = timeout;

        if (error)
                return error;

        return 0;
}
